scripts.factorial_mod:
def solve(inputs: dict) -> float:
    N = int(inputs['N'])
    MOD = int(inputs['MOD'])

    # Calculate N! mod MOD
    result = 1
    for i in range(1, N + 1):
        result = (result * i) % MOD

    return float(result)

scripts.divide_and_sum:
def solve(inputs: dict) -> float:
    A = inputs['A']
    B = inputs['B']

    # Divide each A_i by B_i and keep the integer part, then sum
    total = sum(int(A[i] // B[i]) for i in range(len(A)))

    return float(total)

scripts.find_gcd:
def solve(inputs: dict) -> float:
    import math

    VALUES = inputs['VALUES']

    # Compute GCD of all values
    result = VALUES[0]
    for i in range(1, len(VALUES)):
        result = math.gcd(result, VALUES[i])

    return float(result)

scripts.lcg_iteration:
def solve(inputs: dict) -> float:
    s = int(inputs['SEED'])
    A = int(inputs['A'])
    B = int(inputs['B'])
    M = int(inputs['M'])
    K = int(inputs['K'])

    # Repeat K times: s = (A * s + B) % M
    for _ in range(K):
        s = (A * s + B) % M

    return float(s)

scripts.continued_fraction:
def solve(inputs: dict) -> float:
    TERMS = inputs['TERMS']

    # Compute convergents using the recurrence relation
    # p_n = a_n * p_{n-1} + p_{n-2}
    # Start with p_{-1} = 0, p_0 = a_0

    if len(TERMS) == 0:
        return 0.0

    p_prev2 = 0  # p_{-1}
    p_prev1 = TERMS[0]  # p_0

    for i in range(1, len(TERMS)):
        p_new = TERMS[i] * p_prev1 + p_prev2
        p_prev2 = p_prev1
        p_prev1 = p_new

    return float(p_prev1)

